Item.method_code:
const srcElement = window.event ? window.event.srcElement : event.srcElement ? event.srcElement : event.target;
const item = parent.item;
const hierarchy = aras.getItemProperty(item, 'classification_hierarchy');
if (hierarchy) {
	const treeStructure = JSON.parse(hierarchy);
	const edges = {};
	treeStructure.forEach(function(edge) {
		const from = edge.fromRefId || 'roots';
		const to =  edge.toRefId;
		if (!edges[from]) {
			edges[from] = [];
		}
		edges[from].push(to);
	});
	aras.getItemRelationshipsEx(item, 'xClass');
	const root = item.selectSingleNode('Relationships/Item[ref_id=\'' + edges.roots[0] + '\']');
	const oldLabels = root.selectNodes('./*[name()=\'i18n:label\']');
	Array.prototype.forEach.call(oldLabels, function(oldLabel) {
		oldLabel.parentNode.removeChild(oldLabel);
	});
	aras.setItemProperty(root, 'label', srcElement.value);
	const labels = parent.item.selectNodes('./*[name()=\'i18n:label\']');
	Array.prototype.forEach.call(labels, function(label) {
		root.appendChild(label);
	});
	root.setAttribute('action', 'update');
}
